import openpyxl
path='/root/data/workbook.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
data=wb['Data']

# find cells with value 2018..2022 in Data
years={2018,2019,2020,2021,2022}
found=[]
for row in data.iter_rows():
    for cell in row:
        v=cell.value
        if v in years:
            found.append((cell.coordinate, v))

print('Found year headers:', found[:50], 'count=',len(found))

# Also print row 20-22 for columns F-L with coordinates
for r in range(18,26):
    vals=[]
    for c in range(1,13):
        v=data.cell(r,c).value
        if v is None: continue
        vals.append((openpyxl.utils.get_column_letter(c)+str(r), v))
    if vals:
        print('Row',r, vals)

# Print columns H-L first 25 rows to spot header strings
for r in range(1,26):
    row=[]
    for c in range(8,13):
        v=data.cell(r,c).value
        row.append(v)
    if any(v is not None for v in row):
        print('H-L row',r, row)
